def _paragraphs(value):
    chunks = []
    for paragraph in (part.strip() for part in value.split("\n\n")):
        if not paragraph:
            continue
        chunks.append(
            "<p>" + "<br>".join(escape(line.strip()) for line in paragraph.splitlines()) + "</p>"
        )
    return "".join(chunks)


