def seed_simplified_post_layouts_and_body_html(apps, schema_editor):
    LayoutPreset = apps.get_model("content", "LayoutPreset")
    Post = apps.get_model("content", "Post")

    for preset in SIMPLIFIED_POST_LAYOUTS:
        LayoutPreset.objects.update_or_create(
            scope="post",
            key=preset["key"],
            defaults={
                "name": preset["name"],
                "description": preset["description"],
                "preview_static_path": "",
                "allowed_block_types": [],
                "required_fields": ["title", "teaser", "body_html"],
                "max_images": 1,
                "is_active": True,
            },
        )

    for post in Post.objects.prefetch_related(
        "blocks",
        "blocks__image",
        "blocks__carousel__items__image",
    ):
        changed_fields = []
        if post.status == "review":
            post.status = "draft"
            changed_fields.append("status")
        if not post.body_html:
            post.body_html = _build_body_html(post)
            changed_fields.append("body_html")
        if changed_fields:
            post.save(update_fields=changed_fields + ["updated_at"])


def remove_simplified_post_layouts(apps, schema_editor):
    LayoutPreset = apps.get_model("content", "LayoutPreset")
    LayoutPreset.objects.filter(
        scope="post",
        key__in=[preset["key"] for preset in SIMPLIFIED_POST_LAYOUTS],
    ).delete()


